import java.util.Scanner;

public class Main {
    static final int MAXN = 10;
    static final long MOD = 1000000007L;
    static int[][] p = new int[MAXN][MAXN];
    static int[] id = new int[64];
    static int count_id = 0;
    static int[] X_array = new int[1048576];
    static int[] Y_array = new int[1048576];

    static long fastExponent(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }

    static long modInverse(long x) {
        return fastExponent(x, MOD - 2);
    }

    static void updateAdd(int[] arr, int index, int y) {
        arr[index] += y;
        if (arr[index] >= MOD) arr[index] -= MOD;
    }

    static void updateSub(int[] arr, int index, int y) {
        arr[index] -= y;
        if (arr[index] < 0) arr[index] += MOD;
    }

    static void fwTransform(int[] arr, int mode) {
        int N = 1048576;
        for (int len = 2; len <= N; len <<= 1) {
            for (int start = 0; start < N; start += len) {
                for (int k = start; k < start + (len >> 1); ++k) {
                    if (mode == 1) {
                        updateAdd(arr, k, arr[k + (len >> 1)]);
                    } else {
                        updateSub(arr, k, arr[k + (len >> 1)]);
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = sc.nextInt();
                p[i][j] = (int) ((long) val * modInverse(100) % MOD);
            }
        }

        if (n < 6) {
            for (int i = n; i < 6; i++) {
                p[i][i] = 1;
            }
            n = 6;
        }

        int A = (1 << 6) - 1;

        for (int i = 0; i < 64; i++) {
            if (Integer.bitCount(i) == 3) {
                id[i] = count_id++;
            }
        }

        for (int mask = 0; mask < (1 << 18); mask++) {
            int msk1 = mask & A;
            int msk2 = (mask >> 6) & A;
            int msk3 = (mask >> 12) & A;
            int combined_mask = 0;
            long probability = 1;

            for (int j = 0; j < 6; j++) {
                if (((msk1 >> j) & 1) == 1) {
                    probability = (probability * p[0][j]) % MOD;
                } else {
                    probability = (probability * (MOD + 1 - p[0][j])) % MOD;
                }
            }
            for (int j = 0; j < 6; j++) {
                if (((msk2 >> j) & 1) == 1) {
                    probability = (probability * p[1][j]) % MOD;
                } else {
                    probability = (probability * (MOD + 1 - p[1][j])) % MOD;
                }
            }
            for (int j = 0; j < 6; j++) {
                if (((msk3 >> j) & 1) == 1) {
                    probability = (probability * p[2][j]) % MOD;
                } else {
                    probability = (probability * (MOD + 1 - p[2][j])) % MOD;
                }
            }
            if (probability == 0) continue;

            for (int a = 0; a < 6; a++) {
                if (((msk1 >> a) & 1) == 1) {
                    for (int b = 0; b < 6; b++) {
                        if (a == b) continue;
                        if (((msk2 >> b) & 1) == 1) {
                            for (int c = 0; c < 6; c++) {
                                if (a == c || b == c) continue;
                                if (((msk3 >> c) & 1) == 1) {
                                    int nmsk = (1 << a) | (1 << b) | (1 << c);
                                    combined_mask |= 1 << id[nmsk];
                                }
                            }
                        }
                    }
                }
            }
            updateAdd(Y_array, combined_mask, (int) probability);
        }

        for (int mask = 0; mask < (1 << 18); mask++) {
            int msk1 = mask & A;
            int msk2 = (mask >> 6) & A;
            int msk3 = (mask >> 12) & A;
            int combined_mask = 0;
            long probability = 1;

            for (int j = 0; j < 6; j++) {
                if (((msk1 >> j) & 1) == 1) {
                    probability = (probability * p[3][j]) % MOD;
                } else {
                    probability = (probability * (MOD + 1 - p[3][j])) % MOD;
                }
            }
            for (int j = 0; j < 6; j++) {
                if (((msk2 >> j) & 1) == 1) {
                    probability = (probability * p[4][j]) % MOD;
                } else {
                    probability = (probability * (MOD + 1 - p[4][j])) % MOD;
                }
            }
            for (int j = 0; j < 6; j++) {
                if (((msk3 >> j) & 1) == 1) {
                    probability = (probability * p[5][j]) % MOD;
                } else {
                    probability = (probability * (MOD + 1 - p[5][j])) % MOD;
                }
            }
            if (probability == 0) continue;

            for (int a = 0; a < 6; a++) {
                if (((msk1 >> a) & 1) == 1) {
                    for (int b = 0; b < 6; b++) {
                        if (a == b) continue;
                        if (((msk2 >> b) & 1) == 1) {
                            for (int c = 0; c < 6; c++) {
                                if (a == c || b == c) continue;
                                if (((msk3 >> c) & 1) == 1) {
                                    int nmsk = (1 << a) | (1 << b) | (1 << c);
                                    nmsk ^= A;
                                    updateAdd(X_array, nmsk, (int) probability);
                                }
                            }
                        }
                    }
                }
            }
        }

        fwTransform(X_array, 1);
        fwTransform(Y_array, 1);
        for (int i = 0; i < 1048576; i++) {
            X_array[i] = (int) ((long) X_array[i] * Y_array[i] % MOD);
        }
        fwTransform(X_array, -1);
        long answer = 0;
        for (int i = 1; i < 1048576; i++) {
            answer += X_array[i];
        }
        System.out.println(answer % MOD);
        sc.close();
    }
}
